package export_ohrats_rc_scheduler_management

import (
	witTypes "go.bytecodealliance.org/pkg/wit/types"
	types "wit_component/ohrats_rc_scheduler_types"
	sched "wit_component/schedule"
)

func ListSchedules() witTypes.Result[[]types.Definition, string] {
	schedules, err := sched.List()
	if err != nil {
		return witTypes.Err[[]types.Definition, string](err.Error())
	}
	return witTypes.Ok[[]types.Definition, string](schedules)
}

func GetSchedule(id string) witTypes.Result[witTypes.Option[types.Definition], string] {
	definition, exists, err := sched.Get(id)
	if err != nil {
		return witTypes.Err[witTypes.Option[types.Definition], string](err.Error())
	}
	if !exists {
		return witTypes.Ok[witTypes.Option[types.Definition], string](
			witTypes.None[types.Definition](),
		)
	}
	return witTypes.Ok[witTypes.Option[types.Definition], string](
		witTypes.Some(definition),
	)
}

func UpsertSchedule(definition types.Definition) witTypes.Result[witTypes.Unit, string] {
	if err := sched.Upsert(definition); err != nil {
		return witTypes.Err[witTypes.Unit, string](err.Error())
	}
	return witTypes.Ok[witTypes.Unit, string](witTypes.Unit{})
}

func RemoveSchedule(id string) witTypes.Result[bool, string] {
	removed, err := sched.Remove(id)
	if err != nil {
		return witTypes.Err[bool, string](err.Error())
	}
	return witTypes.Ok[bool, string](removed)
}

func SetEnabled(id string, enabled bool) witTypes.Result[bool, string] {
	updated, err := sched.SetEnabled(id, enabled)
	if err != nil {
		return witTypes.Err[bool, string](err.Error())
	}
	return witTypes.Ok[bool, string](updated)
}
